sys_script_include.script:
var BaseUtils = Class.create();
BaseUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    manageValidation: function() {
        var grBase = new GlideRecord('x_1593193_bases_bases');
        var baseManage = this.getParameter('sysparm_baseManage');
        grBase.addQuery('base_manage', baseManage);
        grBase.query();
        if (grBase.next()) {
            return 'true';
        } else {
            return 'false';
        }
    },
    nameValidation: function() {
        var grBase = new GlideRecord('x_1593193_bases_bases');
        var baseName = this.getParameter('sysparm_baseName');
        grBase.addQuery('name', baseName);
        grBase.query();
        if (grBase.next()) {
            return 'true';
        } else {
            return 'false';
        }
    },
    cityStateValidation: function() {
        var grBase = new GlideRecord('x_1593193_bases_bases');
        var baseCity = this.getParameter('sysparm_baseCity');
        var baseState = this.getParameter('sysparm_baseState');
        grBase.addQuery('city', baseCity);
        grBase.addQuery('state', baseState);
        grBase.query();
        if (grBase.next()) {
            return 'true';
        } else {
            return 'false';
        }
    },
    type: 'BaseUtils'
});
